VARY vec3 vId;
VARY float vDepth;
uniform float uFogOn;
void main()
{
 if (uFogOn > 0.5 && vDepth > 140.0) discard; // far plane only with fog (FUN_0010097c)
 FRAG_COLOR = vec4(vId, 1.0);
}

ATTR vec3 aPos;
ATTR vec3 aId;
uniform mat4 uViewProj;
uniform mat4 uView;
VARY vec3 vId;   // one id per face: every vertex of a face carries the same value
VARY float vDepth;
void main()
{
 vId = aId;
 vDepth = (uView * vec4(aPos, 1.0)).z;
 gl_Position = uViewProj * vec4(aPos, 1.0);
}

VARY vec2 vUv;
VARY float vDepth;
uniform sampler2D uLayer;
uniform vec3 uFogColor;
uniform vec2 uFog;
void main()
{
 if (uFog.y > 0.0 && vDepth > 140.0) discard;
 vec4 L = TEX2D(uLayer, vUv);
 float n = floor(L.a * 255.0 + 0.5);
 if (n < 0.5) discard;
 float k = exp2(-n);
 float f = 0.0;
 if (uFog.y > 0.0) f = clamp((vDepth - uFog.x) / max(uFog.y - uFog.x, 0.001), 0.0, 1.0);
 FRAG_COLOR = vec4(L.rgb * (1.0 - f) + uFogColor * (f * (1.0 - k)), k);
}

ATTR vec3 aPos;
ATTR vec2 aLayerUv;
uniform mat4 uViewProj;
uniform mat4 uView;
VARY vec2 vUv;
VARY float vDepth;
void main()
{
 vUv = aLayerUv;
 vDepth = (uView * vec4(aPos, 1.0)).z;
 gl_Position = uViewProj * vec4(aPos, 1.0);
}

VARY HP vec2 vUv0;
VARY HP vec2 vUv1;
VARY float vDepth;
uniform sampler2D uTex;
uniform sampler2D uLightmap;
uniform sampler2D uIndex;
uniform sampler2D uLut;
uniform vec2 uPalScale;   // shade table row of an index byte: (255, 0.5) / palette count
uniform vec3 uFogColor;
uniform vec2 uFog;
// variants (ProgramSet): PAL shade-table path, ALPHA_TEST colour key, FOG fog, TEX_ALPHA blending
void main()
{
#if defined(PAL) && !defined(TEX_ALPHA) && !defined(ALPHA_TEST)
 vec4 c = vec4(1.0); // opaque shade-table texel: the colour comes from the index
#else
 vec4 c = TEX2D(uTex, vUv0);
#endif
#ifdef ALPHA_TEST
 if (c.a < 0.5) discard;
#endif
 float Lm = TEX2D(uLightmap, vUv1).r;
#ifdef PAL
 // FUN_001039f0 / FUN_001046e4: v = max(0x20, (0xff00 - L * 256) >> 3), level = v >> 8 =
 // floor((255 - L) / 8); texel = that level in the shade table row of the palette index
 // (FUN_000c8024). The 32-column table is read at u = (255.5 - L) / 256 and
 // v = (index + 0.5) / count: two multiply-adds, no floor or divide (the SGX's cost per pixel)
 vec3 rgb = TEX2D(uLut, vec2(Lm * (-255.0 / 256.0) + (255.5 / 256.0), TEX2D(uIndex, vUv0).r * uPalScale.x + uPalScale.y)).rgb;
#else
 float L = Lm * 255.0;
 float m = max((31.0 - (255.0 - L) / 8.0) / 16.0, 0.0);
 vec3 rgb = min(c.rgb * m, vec3(1.0));
#endif
#ifdef FOG
 float f = clamp((vDepth - uFog.x) / max(uFog.y - uFog.x, 0.001), 0.0, 1.0);
 rgb = mix(rgb, uFogColor, f);
#endif
 FRAG_COLOR = vec4(rgb, c.a);
}

ATTR vec3 aPos;
ATTR vec2 aUv0;
ATTR vec2 aUv1;
uniform mat4 uViewProj;
uniform mat4 uView;
VARY HP vec2 vUv0;
VARY HP vec2 vUv1;
VARY float vDepth;
void main()
{
 vUv0 = aUv0;
 vUv1 = aUv1;
 vDepth = (uView * vec4(aPos, 1.0)).z;
 gl_Position = uViewProj * vec4(aPos, 1.0);
}

VARY HP vec2 vUv;
VARY float vBright;
VARY float vLevelU;
VARY float vDepth;
uniform sampler2D uTex;
uniform sampler2D uIndex;
uniform sampler2D uLut;
uniform vec2 uPalScale;
uniform vec4 uColor;
uniform vec3 uFogColor;
uniform vec2 uFog;
// variants (ProgramSet): PAL shade-table path, ALPHA_TEST colour key, FOG fog
void main()
{
#if defined(PAL) && !defined(TEX_ALPHA) && !defined(ALPHA_TEST)
 vec4 c = uColor;
#else
 vec4 c = TEX2D(uTex, vUv) * uColor;
#endif
#ifdef ALPHA_TEST
 if (c.a < 0.5) discard;
#endif
#ifdef PAL
 // gouraud shade (1 - light) * 0x1F00 (FUN_000b4be8; baked / vertex light alike) -> level =
 // shade >> 8 per pixel (vLevelU)
 vec3 rgb = TEX2D(uLut, vec2(vLevelU, TEX2D(uIndex, vUv).r * uPalScale.x + uPalScale.y)).rgb * uColor.rgb;
#else
 vec3 rgb = min(c.rgb * vBright, vec3(1.0));
#endif
#ifdef FOG
 float f = clamp((vDepth - uFog.x) / max(uFog.y - uFog.x, 0.001), 0.0, 1.0);
 rgb = mix(rgb, uFogColor, f);
#endif
 FRAG_COLOR = vec4(rgb, c.a);
}

ATTR vec3 aPos;
ATTR vec3 aNormal;
ATTR vec2 aUv;      // texels
ATTR float aLight;
ATTR float aBone;   // 0: identity, 1 + n: bone n
uniform mat4 uMVP;      // view-projection * model
uniform vec4 uMVz;      // row 2 of view * model: view z
uniform vec4 uBones[BONE_VECS];   // p * R + T per bone as three columns: x' = (p, 1) . uBones[3b]
uniform int uLit;
uniform vec3 uLightObj; // FUN_000b5490: normalize(-(dir * inverse(world))), object space
uniform vec4 uLightK;   // base, diffuse, min, scale
uniform vec2 uUvScale;  // 1 / texture size
uniform vec2 uUvOffset;
VARY HP vec2 vUv;
VARY float vBright;
VARY float vLevelU;
VARY float vDepth;
void main()
{
 // FUN_000b23e0: only the position goes through the bone matrix
 int b = int(aBone + 0.5) * 3;
 vec4 p = vec4(aPos, 1.0);
 vec4 q = vec4(dot(p, uBones[b]), dot(p, uBones[b + 1]), dot(p, uBones[b + 2]), 1.0);
 if (uLit == 1)
 {
  // FUN_000b4be8: the raw mesh normal against the light in object space; light >= min,
  // times the scale (past 1: shade 0, the brightest level below)
  float l = max(uLightK.x + max(0.0, dot(aNormal, uLightObj)) * uLightK.y, uLightK.z);
  vBright = 31.0 * l / 16.0 * uLightK.w;
 }
 else
 {
  vBright = aLight;
 }
 // shade-table column: shade = level << 8 per vertex, the brightest level 2 (FUN_000ca29c),
 // interpolated; the 32-column table read at level / 32 takes level >> 8 per pixel
 vLevelU = (clamp(31.0 - 16.0 * vBright, 2.0, 31.0) + 0.01) / 32.0;
 vUv = aUv * uUvScale + uUvOffset;
 vDepth = dot(uMVz, q);
 gl_Position = uMVP * q;
}

VARY HP vec2 vUv;
VARY vec4 vColor;
uniform sampler2D uTex;
void main()
{
 FRAG_COLOR = TEX2D(uTex, vUv) * vColor;
}

ATTR vec3 aPos;
ATTR vec2 aUv;
ATTR vec4 aColor;
uniform mat4 uProj;
VARY HP vec2 vUv;
VARY vec4 vColor;
void main()
{
 vUv = aUv;
 vColor = aColor;
 gl_Position = uProj * vec4(aPos, 1.0);
}

VARY HP vec2 vUv;
uniform sampler2D uScene;
uniform sampler2D uHistory;
uniform int uFx;
uniform float uTime;
uniform vec2 uSize;   // scene size in original pixels (320x240 space)
// triangle wave through k = -A..A with period 4A: T(k) = k for |k| <= A
float Tri(float k, float A)
{
 float m = mod(k + A, 4.0 * A);
 return m <= 2.0 * A ? m - A : 3.0 * A - m;
}
void main()
{
 vec2 uv = vUv;
 if (uFx == 8)
 {
  // TwistShader vf2 @e43f0 (ctor FUN_00030f30: amplitude A = 2, phase 0, step 1). Per row the
  // offset starts at the frame phase with direction +1: off += dir, dir reverses once
  // off >= A or off <= -A; source x = clamp(x + off, 0, 319). After the frame the phase walks
  // the same way (one step per game frame). From phase A the walk overshoots and alternates
  // A + 1, A, A + 1, ...
  float A = 2.0;
  float ph = Tri(uTime, A);
  float py = floor((1.0 - uv.y) * 240.0);
  float off = ph >= A ? (mod(py, 2.0) < 0.5 ? A + 1.0 : A) : Tri(ph + 1.0 + py, A);
  uv.x = clamp(uv.x + off / 320.0, 0.0, 1.0);
 }
 vec3 c = TEX2D(uScene, uv).rgb;
 if (uFx == 1)
 {
  // GrayShader vf2 @e3064: the 5-bit blue channel of the RGB565 pixel copied to R, G and B
  c = vec3(floor(c.b * 255.0 / 8.0) * 8.0 / 255.0);
 }
 else if (uFx == 2)
 {
  // MotionBlurShader vf2 @e2950: hist = min(255, cur / 4 + hist * 7 / 8), shown as is
  vec3 h = TEX2D(uHistory, uv).rgb;
  c = min(c * 0.25 + h * 0.875, vec3(1.0));
 }
 else if (uFx == 7)
 {
  // BlindShader vf2 @e3f00: every channel * row / (240 - 1), black on the top row
  float py = floor((1.0 - uv.y) * 240.0);
  c *= py / 239.0;
 }
 FRAG_COLOR = vec4(c, 1.0);
}

ATTR vec3 aPos;
ATTR vec2 aUv;
VARY HP vec2 vUv;
void main()
{
 vUv = aUv;
 gl_Position = vec4(aPos.xy, 0.0, 1.0);
}

ATTR vec3 aPos;
ATTR vec2 aUv;
VARY HP vec2 vUv;
void main()
{
 vUv = aUv;
 gl_Position = vec4(aPos.xy, 0.0, 1.0);
}

VARY HP vec2 vUv;
uniform sampler2D uScene;
void main()
{
 FRAG_COLOR = vec4(TEX2D(uScene, vUv).rgb, 1.0);
}
